properties.put("children", Map.of("type", "array", "items", Map.of("$ref", "#")));
properties.put(
    "attributes",
    Map.of(
        "type",
        "array",
        "items",
        Map.of(
            "type",
            "object",
            "properties",
            attributeProperties,
            "required",
            List.of("name", "value"),
            "additionalProperties",
            false)));

ResponseCreateParams params =
    ResponseCreateParams.builder()
        .model("gpt-6-astra")
        .inputOfResponse(
